    /// <summary>The schema class names <c>as</c> accepts, for the error when it is given another.</summary>
    public static IReadOnlyCollection<string> Names => Factories.Keys;

    /// <summary>
    /// The surface for one schema class, or a throw naming the mistake.
    /// </summary>
    /// <param name="schemaClass">The class name, spelled as the schema spells it.</param>
    /// <param name="resolve">The generic entity resolver the facade holds.</param>
    /// <param name="entities">The server's one entity table.</param>
    public static ScriptSurface For(string schemaClass, Func<global::CounterStrikeSharp.API.Core.CBaseEntity> resolve, CssEntities entities)
    {
        ArgumentException.ThrowIfNullOrEmpty(schemaClass);
        return Factories.TryGetValue(schemaClass, out var make)
            ? make(resolve, entities)
            : throw new ArgumentException(
                $"there is no entity surface for a schema class called '{schemaClass}'; it has to be " +
                "one CounterStrikeSharp binds, spelled as the schema spells it — 'CAK47', 'CBaseDoor'");
    }

    /// <summary>
    /// Builds the table now, at plugin load, so that the first <c>as</c> in a script does
    /// not pay to compile the initializer against the watchdog's budget — the trap the
    /// event switch has.
    /// </summary>
    public static void Warm() => _ = Factories.Count;
}
